const modes={normal:'Normal · 4+',advantage:'Vantagem · 3+',disadvantage:'Desvantagem · 5+'};
let restored;try{const response=await apiFetch(sceneEndpoint);if(!response.ok)throw Error();restored=await response.json();}catch{document.querySelectorAll('button').forEach(b=>b.disabled=true);$('#feedback').textContent='Não foi possível carregar a cena salva. Reconecte ao servidor; nenhuma ação foi liberada.';throw Error('Servidor da cena indisponível.');}
const serverDigivice=restored.capabilities?.digivice===true;
let state=restored.state,revision=restored.revision,busy=false,formContext=null;
const cmd=(command,...args)=>({command,args});
async function commit(command,...args){const response=await apiFetch(sceneEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({command,args,revision,requestId:crypto.randomUUID(),resolutionId:state.activeResolutionId,mode:viewMode})});const data=await response.json();if(data.state){revision=data.revision;if(data.maintenance){maintenanceChoices.clear();for(const [id,value] of Object.entries(data.maintenance))maintenanceChoices.set(id,value);}if(!response.ok){state=data.state;playerId=data.actorId;rebuildSelectors();applyScenePresentation();render();}}if(!response.ok)throw Error(data.error||'A alteração não foi salva.');return data.state;}
const imageData=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});
