async function choosePlayer(id){if(id&&!canChoose(state,viewMode,playerId,id,busy))return;try{if(id){busy=true;state=await commit('claim',id);}playerId=id;if(id)$('#operator').value=id;}catch(error){report(error);}finally{busy=false;render();}}
function controlsEntity(id){const a=selectedActor();return viewMode==='narrator'?(id===a.id||state.humans.some(h=>h.id===id&&h.pairId===a.pairId)):canControl(id);}
function canControl(id){return canOperate(state,viewMode,playerId,id);}
