for(const key of Object.keys(engine.ATTRIBUTES))$('#lab'+key[0].toUpperCase()+key.slice(1)).addEventListener('input',e=>{if(!npcDraft||e.target.value==='')return;const rule=NPC_ATTRIBUTE_RULES[fieldValue('labStage')],others=Object.keys(engine.ATTRIBUTES).filter(k=>k!==key).reduce((sum,k)=>sum+numeric('lab'+k[0].toUpperCase()+k.slice(1)),0);e.target.value=Math.max(rule.min,Math.min(rule.max,rule.total-others,Math.trunc(Number(e.target.value))));updateLabPreview();});
