$('#labForm').addEventListener('submit',async e=>{e.preventDefault();let image=null;try{const file=$('#labImage').files[0];if(file){if(file.type!=='image/png'||file.size>12*1024*1024)throw Error('Escolha um PNG de até 12 MB');image=await imageData(file);}const attrs={};for(const key of Object.keys(engine.ATTRIBUTES))attrs[key]=Number($('#lab'+key[0].toUpperCase()+key.slice(1)).value);if(npcDraft)validateNpcAttributes(fieldValue('labStage'),attrs);const actor=engine.actorById(npcDraft||state,fieldValue('labActor'));const config={actorId:actor.id,formId:fieldValue('labFormId'),name:fieldValue('labName'),stage:fieldValue('labStage'),element:fieldValue('labElement'),digitalAttribute:fieldValue('labDigital'),attributes:attrs,hp:numeric('labHp'),position:{x:numeric('labX'),y:numeric('labY'),scale:numeric('labScale')},unlocked:checked('labUnlocked'),active:checked('labActive'),image:image||fieldValue('labImageLink')||null,conditions:Object.keys(engine.CONDITIONS).filter(id=>checked('condition-'+id)),poisonPower:numeric('labPoison')};if(engine.pairOf(npcDraft||state,actor))Object.assign(config,{level:numeric('labLevel'),bond:numeric('labBond'),energy:numeric('labEnergy')});if(engine.pairOf(npcDraft||state,actor))config.talents=fieldValue('labTalents').split('\n').filter(l=>l.trim()).map((l,i)=>{const [name,rank]=l.split('|');return {id:'talent-'+i,name:name.trim(),rank:Number(rank)};});config.qualities=fieldValue('labQualities').split('\n').filter(l=>l.trim()).map((l,i)=>{const [name,rank]=l.split('|');return {id:'quality-'+i,name:name.trim(),rank:Number(rank)};});config.attacks=fieldValue('labAttacks').split('\n').filter(l=>l.trim()).map((l,i)=>{return npcSignature(l,i);});config.characteristics={body:numeric('labBody'),mind:numeric('labMind'),presence:numeric('labPresence')};config.humanName=fieldValue('labHumanName');if(config.image&&!/^https?:\/\//i.test(config.image)&&!/^data:image\/(png|jpeg|webp);base64,/i.test(config.image))throw Error('Use um link HTTP ou HTTPS.');state=await commit(npcDraft?'createNpc':'configureLab',config,...(npcDraft?[npcSide]:[]));state=await commit('presentation',{actorId:config.actorId,flipped:labFlipped,name:fieldValue('labScene').slice(0,70)||'Cena de Teste'});npcDraft=null;rebuildSelectors();$('#labDialog').close();message('Configuração aplicada. A cena continua local e fictícia.');render();}catch(error){setText('labPreview',error.message);}});
