function openNpc(side){if(busy||viewMode!=='narrator')return;try{npcSide=side;npcDraft=draftNpc(state,side);setLabMode(true);const actor=npcDraft.actors.at(-1);$('#labScene').value=state.scene.name;$('#labActor').innerHTML=option(actor.id,'NOVO NPC');$('#labActor').value=actor.id;$('#labActor').disabled=true;$('#labFormId').disabled=true;fillLab(true);$('#labDialog').showModal();}catch(e){report(e);}}
