function renderResolutionQueue(){const entries=(state.resolutions||[]).filter(r=>r.round===state.round);$('#resolutionQueue').innerHTML=entries.map(r=>{const p=r.pending||r.result,c=p?.context;return '<button data-resolution="'+r.id+'" class="resolution-ticket '+(r.id===state.activeResolutionId?'selected':'')+'"><b>'+escape(c?c.actor.name+' → '+c.target.name:p?.name||'Ação')+'</b><span>'+escape(c?.signature?.name||p?.action||'Ataque comum')+'</span><small>'+(r.pending?(engine.awaitingMultiAttacks(state,r.pending)?'CONFIRMAR OS DOIS ATAQUES':r.pending.attackConfirmed===false?'REVISAR ATAQUE':r.pending.kind==='attack'&&!r.pending.dodge?'AGUARDANDO ESQUIVA':r.pending.defenseConfirmed===false?'REVISAR ESQUIVA':'APLICAR RESULTADO'):'✓ RESOLVIDO')+'</small></button>';}).join('');$('#resolutionQueue').querySelectorAll('button').forEach(b=>{b.disabled=busy;b.onclick=()=>{state=engine.selectResolution(state,b.dataset.resolution);render();};});setText('queueCount',engine.pendingResolutions(state).length+' PENDENTES');}
$('#humanObserve').onclick=async()=>{const human=selectedHuman(),coordinates=human.observedRound===state.round-1;if(await confirmation(coordinates?'Dar Coordenadas usa a ação do Humano. O próximo ataque do seu Digimon nesta rodada recebe +1d6. Confirmar?':'Observar usa a ação do Humano e libera Dar Coordenadas somente na próxima rodada. Confirmar?'))await run(cmd(coordinates?'giveCoordinates':'observe',human.id),coordinates?'COORDENADAS ENVIADAS':'OBSERVANDO');};


$('#loadForum').onclick=async()=>{if(viewMode!=='narrator'||busy)return;const button=$('#loadForum');button.disabled=true;setText('forumStatus','Lendo a lista pública de fichas aprovadas…');try{const response=await apiFetch('/api/forum/sheets'),data=await response.json();if(!response.ok)throw Error(data.error);$('#forumSheets').replaceChildren(...data.sheets.map(sheet=>{const b=document.createElement('button');b.textContent=sheet.title;b.onclick=()=>readForumSheet(sheet);return b;}));setText('forumStatus',data.sheets.length+' fichas públicas. Selecione para revisar e adicionar à cena local.');}catch(e){setText('forumStatus',e.message);}finally{button.disabled=false;}};
async function readForumSheet(sheet){if(viewMode!=='narrator'||busy)return;setText('forumStatus','Lendo '+sheet.title+'…');$('#forumSheets').querySelectorAll('button').forEach(b=>b.disabled=true);try{const response=await apiFetch('/api/forum/sheet?path='+encodeURIComponent(sheet.path)),data=await response.json();if(!response.ok)throw Error(data.error);const parsed=parsePublicSheet(data.html,{title:data.title,url:data.url}),form=parsed.forms.rookie;setText('forumStatus',[parsed.human.name+' / '+form.name,'Nível '+parsed.level+' · PV '+parsed.hp+' · Energia '+parsed.human.energy+' · PL '+parsed.bond,...parsed.warnings].join(' — '));$('#allyDialog').close();if(await confirmation('Adicionar '+parsed.human.name+' / '+form.name+' como aliado? Nível '+parsed.level+', PV '+parsed.hp+'. '+(parsed.warnings.length?'Confira: '+parsed.warnings.join(' '):'Leitura da ficha pública; nenhuma alteração será enviada ao fórum.'))){state=await commit('importParticipant',parsed);rebuildSelectors();$('#operator').value=state.actors.at(-1).id;render();message('Ficha pública adicionada à sessão local. Retrato e atributos importados.');}}catch(e){setText('forumStatus',e.message);}finally{$('#forumSheets').querySelectorAll('button').forEach(b=>b.disabled=false);}}

function renderIncoming(){const a=selectedActor(),h=state.humans.find(h=>h.pairId===a.pairId),entries=[...engine.incomingAttacks(state,a.id),...(h?engine.incomingAttacks(state,h.id):[])];const root=$('#incomingBanner');root.hidden=!entries.length||!canControl(a.id);root.replaceChildren();for(const entry of entries){const p=entry.pending,b=document.createElement('button');b.className='primary';b.textContent=engine.awaitingMultiAttacks(state,p)?'MULTI-ATTACK // AGUARDANDO SEGUNDO ATAQUE':p.attackConfirmed===false?'ATAQUE RECEBIDO // AGUARDANDO ATACANTE':!p.dodge?'⚡ ESQUIVAR AGORA // '+p.context.target.name:'REVISAR DEFESA // '+p.context.target.name;b.disabled=busy||p.attackConfirmed===false||engine.awaitingMultiAttacks(state,p);b.onclick=()=>{state=engine.selectResolution(state,entry.id);render();if(!p.dodge)openAction('dodge');else openCommands();};root.append(b);}const note=document.createElement('small');note.textContent='Resolva a defesa antes de iniciar um ataque com o participante atingido.';root.append(note);}
$('#editResources').onclick=()=>{if(viewMode!=='narrator'||busy)return;const a=selectedActor(),h=state.humans.find(h=>h.pairId===a.pairId),p=engine.pairOf(state,a);setText('resourceTitle','Recursos // '+engine.currentForm(a).name);$('#resourceHp').value=a.hp;$('#resourceHp').max=engine.markers(engine.currentForm(a)).hp;for(const id of ['resourceEnergy','resourceBond'])$('#'+id).closest('label').hidden=!h;if(h){$('#resourceEnergy').value=h.energy;$('#resourceEnergy').max=9+p.level;$('#resourceBond').value=p.bond;$('#resourceBond').max=p.level+5;}setText('resourceError','');$('#resourceDialog').showModal();};
