// Presentation can be local, but combat always resumes from the saved server revision.
let refreshing=false;
async function refreshSavedScene(){if(refreshing||document.hidden||busy||document.querySelector('dialog[open]:not(#commandDialog)'))return;refreshing=true;try{const response=await apiFetch(sceneEndpoint);if(!response.ok)return;const saved=await response.json();if(!busy&&saved.revision>revision){state=saved.state;revision=saved.revision;playerId=saved.actorId;maintenanceChoices.clear();for(const [id,value] of Object.entries(saved.maintenance||{}))maintenanceChoices.set(id,value);maintenancePairId=null;rebuildSelectors();applyScenePresentation();render();}}catch{}finally{refreshing=false;}}
setInterval(refreshSavedScene,4000);window.addEventListener('focus',refreshSavedScene);

