function mountTargetCards(){const select=$('#cfgTarget');if(!select)return;select.parentElement.hidden=true;const fieldset=document.createElement('fieldset');fieldset.className='target-picker';fieldset.innerHTML='<legend>ESCOLHA O ALVO</legend>';for(const option of select.options){const entity=engine.entityById(state,option.value),human=!!entity.characteristics,f=human?null:engine.currentForm(entity),label=document.createElement('label');label.className='target-card';const input=document.createElement('input');input.type='radio';input.name='targetCard';input.value=entity.id;input.checked=select.value===entity.id;input.required=true;const img=document.createElement('img');img.src=human?entity.image:f.image;img.alt='';const info=document.createElement('span');info.innerHTML='<small>'+(human?'HUMANO':'DIGIMON')+'</small><b>'+escape(engine.entityName(entity))+'</b><span>'+(human?'ENERGIA':'PV')+' '+engine.entityLife(entity)+' / '+(human?9+(engine.pairOf(state,entity)?.level||1):engine.markers(f).hp)+'</span>';input.addEventListener('change',()=>{select.value=input.value;updatePreview();});label.append(input,img,info);fieldset.append(label);}select.parentElement.after(fieldset);}
function openDigivice(){const human=selectedHuman(),pair=selectedPair();if(!human||!canControl(human.id))return;const options=digiviceOptions(human,pair.level);formContext={kind:'digivice'};setText('actionTitle','FUNÇÕES DO DIGIVICE');$('#actionFields').innerHTML='<p class="digivice-intro">Cada ativação usa a ação do Humano. Melhorias e usos são lidos da ficha e salvos nesta cena.</p>'+(options.error?'<p>'+escape(options.error)+'</p>':'')+'<div class="digivice-function-grid">'+['Booster','Protocolos Especiais','Scanner de Cards'].map((name,i)=>'<label class="digivice-function"><input type="radio" name="digiviceFunction" value="'+name+'" '+(i===2?'disabled':'')+' '+(i===0?'checked':'')+'><b>'+name+'</b><small>'+(i===0?(options.booster.rank?'Nível '+options.booster.rank+' · '+Math.max(0,options.booster.limit-options.booster.used)+' uso(s) restante(s)':'Não instalado'):i===1?(options.protocols.length+' protocolo(s) instalado(s)'):'Em breve · bloqueado')+'</small></label>').join('')+'</div><input type="hidden" id="cfgFunction" value="Booster"><div id="boosterFields">'+select('cfgBoosterKind','PRÓXIMA ROLAGEM DO PARCEIRO',option('attack','Ataque · Vantagem')+'<option value="dodge" '+(options.booster.rank<2?'disabled':'')+'>Esquiva · Vantagem (Nível 2+)</option>')+'</div><div id="protocolFields" hidden>'+select('cfgProtocol','PROTOCOLO INSTALADO',options.protocols.map(d=>'<option value="'+d.id+'" '+(d.used||d.error?'disabled':'')+'>'+escape(d.protocol+(d.detail?' — '+d.detail:'')+(d.used?' · Usado':d.error?' · Revisar ficha':''))+'</option>').join(''))+'</div>';document.querySelectorAll('[name="digiviceFunction"]').forEach(input=>input.onchange=()=>{$('#cfgFunction').value=input.value;updateDigivicePreview();});$('#confirmAction').textContent='ATIVAR · AÇÃO DO HUMANO';$('#actionDialog').showModal();updateDigivicePreview();}
function updateDigivicePreview(){const human=selectedHuman(),actor=selectedAlly(),o=digiviceOptions(human,selectedPair().level),booster=fieldValue('cfgFunction')==='Booster',protocol=o.protocols.find(d=>d.id===fieldValue('cfgProtocol'));$('#boosterFields').hidden=!booster;$('#protocolFields').hidden=booster;let unavailable=o.error||(!human.remaining?'Ação do Humano já utilizada.':'');if(engine.entityPending(state,actor.id)||engine.incomingAttacks(state,actor.id).some(r=>r.pending.dodge))unavailable='Aplique a rolagem pendente do parceiro primeiro.';if(booster){if(!o.booster.rank)unavailable='Booster não instalado na ficha.';else if(o.booster.used>=o.booster.limit)unavailable='Usos de Booster esgotados neste combate.';else if(actor.boosterNext)unavailable='Já há um Booster aguardando a próxima rolagem.';}else if(!protocol||protocol.used||protocol.error)unavailable=protocol?.error||'Nenhum protocolo disponível neste combate.';if(!serverDigivice&&!unavailable)unavailable='Ativação do Digivice temporariamente indisponível nesta cena.';const descriptions={'Troca de Elemento':'Altera o elemento do parceiro e dos ataques de assinatura para '+protocol?.element+'.','Reforço de PV':'+10 PV atuais e máximos; esses 10 PV desaparecem ao terminar o efeito.','Reforço de Esquiva':'+1d6 na Esquiva.','Reforço de Dano':'+2 no dano base.','Qualidade Temporária':'Qualidade '+protocol?.quality+' de Rank 2.','Ataque Temporário':'Ataque '+protocol?.attack?.name+' no maior Rank dos ataques da forma atual.'};setText('configPreview',unavailable||(booster?'Vantagem na próxima rolagem de '+(fieldValue('cfgBoosterKind')==='dodge'?'Esquiva':'Ataque')+' do parceiro. Não gasta PL nem a ação do Digimon.':(descriptions[protocol.protocol]+' Dura até concluir a próxima ação do Digimon. Uma ativação deste protocolo por combate.')));$('#confirmAction').disabled=!!unavailable;}
